create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, display_name text, role text not null default 'student' check(role in ('admin','student')));
create or replace function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name','')) on conflict do nothing; return new; end; $$;
drop trigger if exists auth_profile_created on auth.users;
create trigger auth_profile_created after insert on auth.users for each row execute procedure public.new_profile();
create table if not exists public.departments(id uuid primary key default gen_random_uuid(),name text not null,description text,sort_order int default 0,is_active boolean default true,created_at timestamptz default now());
create table if not exists public.specializations(id uuid primary key default gen_random_uuid(),department_id uuid references public.departments(id) on delete cascade,name text not null,description text,is_active boolean default true,created_at timestamptz default now());
create table if not exists public.subjects(id uuid primary key default gen_random_uuid(),specialization_id uuid references public.specializations(id) on delete cascade,name text not null,semester text,description text,is_active boolean default true,created_at timestamptz default now());
create table if not exists public.materials(id uuid primary key default gen_random_uuid(),subject_id uuid references public.subjects(id) on delete cascade,title text not null,description text,file_url text not null,created_at timestamptz default now());
create table if not exists public.site_settings(id int primary key default 1 check(id=1),site_name text default 'بوابة الكلية',welcome_text text default 'المكتبة الأكاديمية للكلية',whatsapp text,telegram text,students_closed boolean default false,closed_message text default 'الموقع مغلق مؤقتاً للصيانة.');
insert into public.site_settings(id) values(1) on conflict do nothing;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
alter table public.profiles enable row level security;
alter table public.departments enable row level security;alter table public.specializations enable row level security;alter table public.subjects enable row level security;alter table public.materials enable row level security;alter table public.site_settings enable row level security;
create policy "read own profile" on public.profiles for select using(id=auth.uid() or public.is_admin());
create policy "admin update profiles" on public.profiles for update using(public.is_admin()) with check(public.is_admin());
create policy "public read departments" on public.departments for select using(is_active or public.is_admin());
create policy "admin all departments" on public.departments for all using(public.is_admin()) with check(public.is_admin());
create policy "public read specializations" on public.specializations for select using(is_active or public.is_admin());
create policy "admin all specializations" on public.specializations for all using(public.is_admin()) with check(public.is_admin());
create policy "public read subjects" on public.subjects for select using(is_active or public.is_admin());
create policy "admin all subjects" on public.subjects for all using(public.is_admin()) with check(public.is_admin());
create policy "public read materials" on public.materials for select using(true);
create policy "admin all materials" on public.materials for all using(public.is_admin()) with check(public.is_admin());
create policy "public read settings" on public.site_settings for select using(true);
create policy "admin all settings" on public.site_settings for all using(public.is_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('university-files','university-files',true,26214400,array['application/pdf','image/png','image/jpeg','image/webp']) on conflict(id) do nothing;
create policy "public read university files" on storage.objects for select using(bucket_id='university-files');
create policy "admin upload university files" on storage.objects for insert with check(bucket_id='university-files' and public.is_admin());
create policy "admin delete university files" on storage.objects for delete using(bucket_id='university-files' and public.is_admin());
